import { encodeBytesBase64 } from "@/lib/tools/base64";
import { formatDigest } from "@/lib/tools/hash";

/**
 * RSA key pair generation with the browser's Web Crypto API (RSA-OAEP with
 * SHA-256, public exponent 65537). Keys are generated by the browser's native
 * cryptographic library and exported as PEM: the public key as SPKI
 * ("BEGIN PUBLIC KEY") and the private key as unencrypted PKCS#8
 * ("BEGIN PRIVATE KEY").
 *
 * The key algorithm is fixed when the key is created: these keys are for
 * RSA-OAEP encryption. The PEM files themselves are standard and can be
 * imported elsewhere, but Web Crypto will not use an OAEP key for signing.
 */

export type RsaKeySize = 2048 | 4096;
export const RSA_KEY_SIZES: RsaKeySize[] = [2048, 4096];

type Subtle = Pick<SubtleCrypto, "generateKey" | "exportKey" | "digest">;

function defaultSubtle(): Subtle | null {
  const subtle = globalThis.crypto?.subtle;
  return subtle && typeof subtle.generateKey === "function" ? subtle : null;
}

/** DER bytes as PEM: Base64 wrapped at 64 characters between BEGIN and END lines (RFC 7468). */
export function toPem(der: Uint8Array, label: string): string {
  const base64 = encodeBytesBase64(der);
  const lines = base64.match(/.{1,64}/g) ?? [];
  return `-----BEGIN ${label}-----\n${lines.join("\n")}\n-----END ${label}-----\n`;
}

/** Decodes a PEM block with the given label back to DER bytes. */
export function fromPem(pem: string, label: string): Uint8Array | null {
  const match = new RegExp(`-----BEGIN ${label}-----([A-Za-z0-9+/=\\s]+)-----END ${label}-----`).exec(pem);
  if (!match) return null;
  return Uint8Array.from(atob(match[1].replace(/\s+/g, "")), (c) => c.charCodeAt(0));
}

export type RsaKeyPair = {
  ok: true;
  publicPem: string;
  privatePem: string;
  /** SHA-256 of the SPKI public key, Base64 without padding (as in OpenSSH and certificate pinning). */
  fingerprint: string;
  bits: RsaKeySize;
  ms: number;
};

export type RsaResult = RsaKeyPair | { ok: false; error: string };

export async function generateRsaKeyPair(bits: RsaKeySize, subtle: Subtle | null = defaultSubtle()): Promise<RsaResult> {
  if (!RSA_KEY_SIZES.includes(bits)) return { ok: false, error: "Choose a key size of 2048 or 4096 bits." };
  if (!subtle) {
    return {
      ok: false,
      error: "This browser does not provide Web Crypto (crypto.subtle), which is needed to generate keys safely. It is only available on secure (HTTPS) pages in up-to-date browsers.",
    };
  }
  try {
    const start = performance.now();
    const pair = await subtle.generateKey(
      { name: "RSA-OAEP", modulusLength: bits, publicExponent: new Uint8Array([1, 0, 1]), hash: "SHA-256" },
      true,
      ["encrypt", "decrypt"],
    );
    const spki = new Uint8Array(await subtle.exportKey("spki", pair.publicKey));
    const pkcs8 = new Uint8Array(await subtle.exportKey("pkcs8", pair.privateKey));
    const fingerprint = formatDigest(new Uint8Array(await subtle.digest("SHA-256", spki)), "base64").replace(/=+$/, "");
    const result: RsaKeyPair = {
      ok: true,
      publicPem: toPem(spki, "PUBLIC KEY"),
      privatePem: toPem(pkcs8, "PRIVATE KEY"),
      fingerprint,
      bits,
      ms: performance.now() - start,
    };
    pkcs8.fill(0);
    return result;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return { ok: false, error: `The key pair could not be generated: ${message}` };
  }
}
